@receiver(layout_image_variables, dispatch_uid="pretix_base_layout_image_variables_questions")
def images_from_questions(sender, *args, **kwargs):
    def get_answer(op, order, event, question_id, etag):
        a = None
        if op.addon_to:
            if 'answers' in getattr(op.addon_to, '_prefetched_objects_cache', {}):
                try:
                    a = [a for a in op.addon_to.answers.all() if a.question_id == question_id][0]
                except IndexError:
                    pass
            else:
                a = op.addon_to.answers.filter(question_id=question_id).first()
        if 'answers' in getattr(op, '_prefetched_objects_cache', {}):
            try:
                a = [a for a in op.answers.all() if a.question_id == question_id][0]
            except IndexError:
                pass
        else:
            a = op.answers.filter(question_id=question_id).first() or a
        if not a or not a.file or not any(a.file.name.lower().endswith(e) for e in (".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tif", ".tiff")):
            return None
        else:
            if etag:
                return hashlib.sha1(a.file.name.encode()).hexdigest()
            return a.file
    d = {}
    for q in sender.questions.all():
        if q.type != Question.TYPE_FILE:
            continue
        d['question_{}'.format(q.identifier)] = {
            'label': _('Question: {question}').format(question=q.question),
            'evaluate': partial(get_answer, question_id=q.pk, etag=False),
            'etag': partial(get_answer, question_id=q.pk, etag=True),
        }
    return d
def get_sizes(size, imgsize):
        raise ThumbnailError('Size %s has errors: crop and minsize cannot be combined.' % size)
def resize_image(image, size):
    image = ImageOps.exif_transpose(image)
    new_size, crop = get_sizes(size, image.size)
    image = image.resize(new_size, resample=Resampling.LANCZOS)
    if crop:
        image = image.crop(crop)
    min_width, min_height = get_minsize(size)
    if min_width > new_size[0] or min_height > new_size[1]:
        padding = math.ceil(max(min_width - new_size[0], min_height - new_size[1]) / 2)
        if image.mode not in ("RGB", "RGBA"):
            image = image.convert('RGB')
        image = ImageOps.expand(image, border=padding, fill="white")
        new_width = max(min_width, new_size[0])
        new_height = max(min_height, new_size[1])
        new_x = (image.width - new_width) // 2
        new_y = (image.height - new_height) // 2
        image = image.crop((new_x, new_y, new_x + new_width, new_y + new_height))
    return image
def create_thumbnail(sourcename, size):
    source = default_storage.open(sourcename)
    image = Image.open(BytesIO(source.read()))
    try:
        image.load()
    except:
        raise ThumbnailError('Could not load image')
    frames = [resize_image(frame, size) for frame in ImageSequence.Iterator(image)]
    image_out = frames[0]
    save_kwargs = {}
    if source.name.lower().endswith('.jpg') or source.name.lower().endswith('.jpeg'):
        target_ext = 'jpeg'
        quality = 95
    elif source.name.lower().endswith('.gif') or source.name.lower().endswith('.png'):
        target_ext = source.name.lower()[-3:]
        quality = None
        image_out.info = image.info
        save_kwargs = {
            'append_images': frames[1:],
            'loop': image.info.get('loop', 0),
            'save_all': True,
        }
    else:
        target_ext = 'png'
        quality = None
    checksum = hashlib.md5(image.tobytes()).hexdigest()
    name = checksum + '.' + size.replace('^', 'c') + '.' + target_ext
    buffer = BytesIO()
    if image_out.mode == "P" and source.name.lower().endswith('.png'):
        image_out = image_out.convert('RGBA')
    if image_out.mode not in ("1", "L", "RGB", "RGBA"):
        image_out = image_out.convert('RGB')
    image_out.save(fp=buffer, format=target_ext.upper(), quality=quality, **save_kwargs)
    imgfile = ContentFile(buffer.getvalue())
    t = Thumbnail.objects.create(source=sourcename, size=size)
    t.thumb.save(name, imgfile)
    return t
def get_thumbnail(source, size):
        return create_thumbnail(source, size)
class OrderPositionViewSet(viewsets.ModelViewSet):
    @action(detail=True, url_name='pdf_image', url_path=r'pdf_image/(?P<key>[^/]+)')
    def pdf_image(self, request, key, **kwargs):
        pos = self.get_object()
        image_vars = get_images(request.event)
        if key not in image_vars:
            raise NotFound('Unknown key')
        image_file = image_vars[key]['evaluate'](pos, pos.order, pos.subevent or self.request.event)
        if image_file is None:
            raise NotFound('No image available')
        if getattr(image_file, 'name', ''):
            ftype, ignored = mimetypes.guess_type(image_file.name)
            extension = os.path.basename(image_file.name).split('.')[-1]
        else:
            img = Image.open(image_file)
            ftype = Image.MIME[img.format]
            extensions = {
                'GIF': 'gif', 'TIFF': 'tif', 'BMP': 'bmp', 'JPEG': 'jpg', 'PNG': 'png'
            }
            extension = extensions.get(img.format, 'bin')
            if hasattr(image_file, 'seek'):
                image_file.seek(0)
        resp = FileResponse(image_file, content_type=ftype or 'application/binary')
        resp['Content-Disposition'] = 'attachment; filename="{}-{}-{}-{}.{}"'.format(
            self.request.event.slug.upper(),
            pos.order.code,
            pos.positionid,
            key,
            extension,
        )
        return resp
logger = logging.getLogger(__name__)
class PortraitImageField(SizeValidationMixin, ExtValidationMixin, forms.FileField):
    def to_python(self, data):
        """
        Based on Django's ImageField
        """
        f = super().to_python(data)
        if f is None:
            return None
        from PIL import Image
        if hasattr(data, 'temporary_file_path'):
            file = data.temporary_file_path()
        else:
            if hasattr(data, 'read'):
                file = BytesIO(data.read())
            else:
                file = BytesIO(data['content'])
        try:
            image = Image.open(file)
            image.verify()
            if hasattr(file, 'seek'):
                file.seek(0)
            image = Image.open(file)
            if image.width > 10_000 or image.height > 10_000:
                raise ValidationError(
                    self.error_messages['max_dimension'],
                    code='max_dimension',
                )
            image.load()
            f.image = image
            f.content_type = Image.MIME.get(image.format)
            image = ImageOps.exif_transpose(image)
            if f._cropdata:
                image = image.crop((
                    f._cropdata.get('x', 0),
                    f._cropdata.get('y', 0),
                    f._cropdata.get('x', 0) + f._cropdata.get('width', image.width),
                    f._cropdata.get('y', 0) + f._cropdata.get('height', image.height),
                ))
                with BytesIO() as output:
                    image.save(output, format=f.image.format)
                    f = SimpleUploadedFile(f.name, output.getvalue(), f.content_type)
                    f.image = image
            if image.width > image.height:
                raise ValidationError(
                    self.error_messages['aspect_ratio_landscape'],
                    code='aspect_ratio_landscape',
                )
            if not 3 / 4 * .95 < image.width / image.height < 3 / 4 * 1.05:
                raise ValidationError(
                    self.error_messages['aspect_ratio_not_3_by_4'],
                    code='aspect_ratio_not_3_by_4',
                )
        except Exception as exc:
            logger.exception('Could not parse image')
            if isinstance(exc, ValidationError):
                raise
            raise ValidationError(
                self.error_messages['invalid_image'],
                code='invalid_image',
            ) from exc
        if hasattr(f, 'seek') and callable(f.seek):
            f.seek(0)
        return f
def validate_uploaded_file_for_valid_image(f):
    if f is None:
        return None
    from PIL import Image
    if hasattr(f, 'temporary_file_path'):
        file = f.temporary_file_path()
    else:
        if hasattr(f, 'read'):
            file = BytesIO(f.read())
        else:
            file = BytesIO(f['content'])
    try:
        try:
            image = Image.open(file)
            image.verify()
        except DecompressionBombError:
            raise ValidationError(_(
                "The file you uploaded has a very large number of pixels, please upload a picture with smaller dimensions."
            ))
        if image.width * image.height > MAX_IMAGE_PIXELS:
            raise ValidationError(_(
                "The file you uploaded has a very large number of pixels, please upload a picture with smaller dimensions."
            ))
    except Exception as exc:
        logger.exception('Could not parse image')
        if isinstance(exc, ValidationError):
            raise
        raise ValidationError(_(
            "Upload a valid image. The file you uploaded was either not an image or a corrupted image."
        )) from exc
    if hasattr(f, 'seek') and callable(f.seek):
        f.seek(0)
