            for item_id, (csize, data) in zip(items, decrypted_repository.get_many(items)):
                chunk_idx.add(item_id, 1, len(data))
                processed_item_metadata_bytes += len(data)
                processed_item_metadata_chunks += 1
                sync.feed(data)
