def valid_msgpacked_dict(d, keys_serialized):
    """check if the data <d> looks like a msgpacked dict"""
    d_len = len(d)
    if d_len == 0:
        return False
    if d[0] & 0xF0 == 0x80:
        offs = 1
    elif d[0] == 0xDE:
        offs = 3
    else:
        return False
    if d_len <= offs:
        return False
    if d[offs] & 0xE0 == 0xA0:
        pass
    elif d[offs] in (0xD9, 0xDA, 0xDB):
        pass
    else:
        return False
    key_serialized = d[offs:]
    return any(key_serialized.startswith(pattern) for pattern in keys_serialized)
